WFJ.Data.add("spell", {
  [440014] = { nil, "Infligge $N1 danni da fuoco ogni $D1.", nil, 0xe0649799, "mu" },
  [440054] = { "Crea uno spirito d'ombra che attacca il bersaglio. L'incantatore riceve il $N1% di mana quando lo Spirito d'Ombra attacca. Dura $D1.", nil, 0x609469be, nil, "um" },
  [440072] = { nil, "Ti senti spettrale.", nil, 0xfcf0fb0b, "mu" },
  [440108] = { nil, "Impossibile attaccare o usare incantesimi.", nil, 0x3f987751, "mu" },
  [440113] = { "I tuoi colpi in mischia hanno una probabilità del $N1% di conferire Morte Improvvisa. Morte Improvvisa consente un uso di Esecuzione indipendentemente dalla salute del bersaglio. Quando Esecuzione è resa possibile da Morte Improvvisa, conservi $N2 rabbia dopo averla usata.", nil, 0x06740070, nil, "um" },
  [440114] = { nil, "Puoi usare Esecuzione una volta indipendentemente dalla salute del bersaglio, e dopo ti resteranno $N1 rabbia.", nil, 0x0287cac8, "mu" },
  [440212] = { { "Infligge $N1 danni da gelo in un raggio di $N2 m.", shape = { "2/0" } }, nil, 0x477a9729, nil, "um" },
  [440213] = { nil, "Il Loa del Sangue vuole una sfida leale, non il massacro degli indifesi! Lascia la tua incursione o affronta la sua ira! Tutti gli attributi e la velocità di movimento ridotti del $N1%.", nil, 0xa7fb784d, "mu" },
  [440236] = { "Usalo sulla ⟦Hypnotic Blade=Lama Ipnotica⟧ per creare un'arma potente.", nil, 0x0c3b5db4, nil, "um" },
  [440285] = { nil, "Il tuo prossimo incantesimo tra ⟦Chain Lightning=Catena di Fulmini⟧, ⟦Chain Heal=Catena di Guarigione⟧ e ⟦Lava Burst=Getto di Lava⟧ sarà a lancio istantaneo.", nil, 0x72a3c338, "mu" },
  [440471] = { nil, "$N1 danni da natura inflitti ogni $D1.", nil, 0x508bfddc, "mu" },
  [440483] = { nil, "Danni fisici inflitti aumentati del $N1%.", nil, 0x07715b9c, "mu" },
  [440484] = { "Danneggiare un bersaglio con Sete di Sangue, ⟦Mortal Strike=Assalto Mortale⟧ o ⟦Shield Slam=Colpo di Scudo⟧ ha una probabilità del $N1% la prima volta e del $N2% ogni volta successiva di farti infuriare (attivando le abilità che richiedono di essere infuriati) e di farti infliggere il $N3% di danni fisici in più per $D1.", nil, 0x50d6447a, nil, "um" },
  [440488] = { "Scatena un'onda di forza davanti al Guerriero, che infligge $N1 danni e stordisce tutti i nemici entro $N2 m in un cono frontale per $D1.", "Stordito.", 0x6860b6dd, 0x27f95286, "uu" },
  [440492] = { "Incidi sul tuo mantello la runa Carne Fresca:\n\n$I1\nDanneggiare un bersaglio con Sete di Sangue, Assalto Mortale o Colpo di Scudo ha una probabilità del $N1% la prima volta e del $N2% ogni volta successiva di farti infuriare (attivando le abilità che richiedono di essere infuriati) e di farti infliggere il $N3% di danni fisici in più per $D1.", nil, 0x5a6bf051, nil, "um" },
  [440493] = { "Ottieni l'abilità Carne Fresca:\n\n$I1\nDanneggiare un bersaglio con Sete di Sangue, Assalto Mortale o Colpo di Scudo ha una probabilità del $N1% la prima volta e del $N2% ogni volta successiva di farti infuriare (attivando le abilità che richiedono di essere infuriati) e di farti infliggere il $N3% di danni fisici in più per $D1.", nil, 0x1c9eb8f1, nil, "um" },
  [440494] = { "Incidi sul tuo mantello la runa Morte Improvvisa:\n\n$I1\nI tuoi colpi in mischia hanno una probabilità del $N1% di conferire Morte Improvvisa. Morte Improvvisa consente un uso di Esecuzione indipendentemente dalla salute del bersaglio. Quando Esecuzione è resa possibile da Morte Improvvisa, conservi $N2 rabbia dopo averla usata.", nil, 0x6d800699, nil, "um" },
  [440495] = { "Ottieni l'abilità Carne Fresca:\n\n$I1\nI tuoi colpi in mischia hanno una probabilità del $N1% di conferire Morte Improvvisa. Morte Improvvisa consente un uso di Esecuzione indipendentemente dalla salute del bersaglio. Quando Esecuzione è resa possibile da Morte Improvvisa, conservi $N2 rabbia dopo averla usata.", nil, 0xc8902296, nil, "um" },
  [440496] = { "Incidi sul tuo mantello la runa Onda d'Urto:\n\n$I1\nScatena un'onda di forza davanti al Guerriero, che infligge $N1 danni e stordisce tutti i nemici entro $N2 m in un cono frontale per $D1.", nil, 0x56e19117, nil, "um" },
  [440497] = { "Ottieni l'abilità Onda d'Urto:\n\n$I1\nScatena un'onda di forza davanti al Guerriero, che infligge $N1 danni e stordisce tutti i nemici entro $N2 m in un cono frontale per $D1.", nil, 0x077d7403, nil, "um" },
  [440505] = { "Conferisce a chi lo beve l'invisibilità per $D1.", "Invisibilità", 0x3fdd20e3, 0x757e6c9b, "uu" },
  [440520] = { "Riduce il costo in mana di Raffica del $N1%, ne riduce il tempo di recupero del $N2%, ne aumenta i danni del $N3% e Raffica non subisce più ritardi di lancio dagli attacchi che infliggono danni. Inoltre, Raffica infligge come danni aggiuntivi il $N4% della tua potenza d'attacco a distanza ogni volta che infligge danni.", nil, 0xe55f42f9, nil, "um" },
  [440529] = { "Riduce del $N1% il costo in mana delle tue trappole e delle tue abilità in mischia, e conferisce ai colpi critici delle tue abilità in mischia e a distanza una probabilità del $N2% di far proseguire il $N3% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0xc71caec4, nil, "um" },
  [440531] = { nil, "Velocità di movimento aumentata del $N1%.", nil, 0xda8c3de1, "mu" },
  [440533] = { "Ottieni il $N1% di velocità di movimento per $D1 dopo aver usato Assalto del Raptor.\n\nLe abilità offensive del tuo famiglio fanno cadere il bersaglio in una Frenesia Idrofoba, che ne aumenta la potenza d'attacco in mischia di $N3 ma ne riduce l'Armatura di $N4 per $D2. I nemici idrofobi non fuggono e ignorano gli effetti di paura e di orrore.", nil, 0xd8584ed2, nil, "um" },
  [440557] = { "Incidi sul tuo mantello la runa Parsimonia:\n\n$I1\nRiduce del $N1% il costo in mana delle tue trappole e delle tue abilità in mischia, e conferisce ai colpi critici delle tue abilità in mischia e a distanza una probabilità del $N2% di far proseguire il $N3% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0x5c9e589a, nil, "um" },
  [440558] = { "Ottieni l'abilità Parsimonia:\n\n$I1\nRiduce del $N1% il costo in mana delle tue trappole e delle tue abilità in mischia, e conferisce ai colpi critici delle tue abilità in mischia e a distanza una probabilità del $N2% di far proseguire il $N3% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0x05ed64c8, nil, "um" },
  [440560] = { "Incidi sul tuo mantello la runa Improved Volley:\n\n$I1\nRiduce il costo in mana di Raffica del $N1%, ne riduce il tempo di recupero del $N2%, ne aumenta i danni del $N3% e Raffica non subisce più ritardi di lancio dagli attacchi che infliggono danni. Inoltre, Raffica infligge come danni aggiuntivi il $N4% della tua potenza d'attacco a distanza ogni volta che infligge danni.", nil, 0x20ba9081, nil, "um" },
  [440561] = { "Ottieni l'abilità Improved Volley:\n\n$I1\nRiduce il costo in mana di Raffica del $N1%, ne riduce il tempo di recupero del $N2%, ne aumenta i danni del $N3% e Raffica non subisce più ritardi di lancio dagli attacchi che infliggono danni. Inoltre, Raffica infligge come danni aggiuntivi il $N4% della tua potenza d'attacco a distanza ogni volta che infligge danni.", nil, 0x15236ce6, nil, "um" },
  [440563] = { "Incidi sul tuo mantello la runa Incidente con Fuga:\n\n$I1\nOttieni il $N1% di velocità di movimento per $D1 dopo aver usato Assalto del Raptor.\n\nLe abilità offensive del tuo famiglio fanno cadere il bersaglio in una Frenesia Idrofoba, che ne aumenta la potenza d'attacco in mischia di $N3 ma ne riduce l'Armatura di $N4 per $D2. I nemici idrofobi non fuggono e ignorano gli effetti di paura e di orrore.", nil, 0x15040a9f, nil, "um" },
  [440564] = { "Ottieni l'abilità Incidente con Fuga:\n\n$I1\nOttieni il $N1% di velocità di movimento per $D1 dopo aver usato Assalto del Raptor.\n\nLe abilità offensive del tuo famiglio fanno cadere il bersaglio in una Frenesia Idrofoba, che ne aumenta la potenza d'attacco in mischia di $N3 ma ne riduce l'Armatura di $N4 per $D2. I nemici idrofobi non fuggono e ignorano gli effetti di paura e di orrore.", nil, 0xa00297a6, nil, "um" },
  [440569] = { "Riduce il tempo di recupero di ⟦Chain Lightning=Catena di Fulmini⟧ del $N1%, fa sì che il tuo ⟦Earthbind Totem=Totem del Vincolo Terrestre⟧ immobilizzi i bersagli per $D1 quando viene posato e aumenta del $N3% i danni periodici inflitti da ⟦Flame Shock=Folgore del Fuoco⟧.", nil, 0x92749d84, nil, "um" },
  [440574] = { nil, "Immobilizzato.", nil, 0x9bb1efcf, "mu" },
  [440580] = { "Evoca due Spirit Wolves al comando dello Sciamano per $D1.", nil, 0x1cc2d3c8, nil, "um" },
  [440586] = { "Stordisce il bersaglio per $D1.", "Stordito.", 0xb330d181, 0x27f95286, "uu" },
  [440589] = { "I tuoi Spirit Wolves ululano, costringendo tutti i nemici ad attaccarli per $D1.", nil, 0x140cc51b, nil, "um" },
  [440591] = { "Rimuove tutti gli effetti di limitazione al movimento e aumenta del $N1% la velocità di movimento tua e dei tuoi Spirit Wolves per $D1.", "Velocità di movimento aumentata del $N1%.", 0x8027f551, 0xda8c3de1, "uu" },
  [440593] = { "Gli attacchi degli Spirit Wolves curano loro e il loro padrone del $N1% dei danni inflitti", "Converte il $N1% dei danni in salute.", 0x39af52d1, 0x6261a453, "uu" },
  [440605] = { "Balza dietro al bersaglio.", nil, 0x17230464, nil, "um" },
  [440609] = { "Gli attacchi degli Spirit Wolves curano loro e il loro padrone di una percentuale dei danni inflitti.", nil, 0x705e00bc, nil, "um" },
  [440610] = { "Rimuove tutti gli effetti di limitazione al movimento.", "Immune a tutti gli effetti di limitazione al movimento.", 0xd1a00509, 0x73d23ab8, "uu" },
  [440630] = { "Incidi sul tuo mantello la runa Spirito Ferino:\n\n$I1\nEvoca due Spirit Wolves al comando dello Sciamano per $D1.", nil, 0x3a18cf25, nil, "um" },
  [440631] = { "Ottieni l'abilità Spirito Ferino:\n\n$I1\nEvoca due Spirit Wolves al comando dello Sciamano per $D1.", nil, 0x634dd6c3, nil, "um" },
  [440632] = { "+$N1 potenza d'attacco solo in Forma Felina, Forma d'Orso e Dire Bear Form.", nil, 0xa798bce2, nil, "um" },
  [440633] = { "Ottieni l'abilità Tempesta, Terra e Fuoco:\n\n$I1\nRiduce il tempo di recupero di Catena di Fulmini del $N1%, fa sì che il tuo Totem del Vincolo Terrestre immobilizzi i bersagli per $D1 quando viene posato e aumenta del $N3% i danni periodici inflitti da Folgore del Fuoco.", nil, 0xb7cb4fb1, nil, "um" },
  [440634] = { "Incidi sul tuo mantello la runa Tempesta, Terra e Fuoco:\n\n$I1\nRiduce il tempo di recupero di Catena di Fulmini del $N1%, fa sì che il tuo Totem del Vincolo Terrestre immobilizzi i bersagli per $D1 quando viene posato e aumenta del $N3% i danni periodici inflitti da Folgore del Fuoco.", nil, 0xb99a4382, nil, "um" },
  [440651] = { "Ogni volta che il bersaglio subisce danni ottiene uno Scudo Sacro, che assorbe $N1 danni e aumenta del $N2% la probabilità del Paladino di infliggere un colpo critico con ⟦Flash of Light=Lampo di Luce⟧ per un massimo di $D1. Non può ottenere questo effetto più di una volta ogni $D2. Dura $D3.", "Assorbe danni e aumenta del $N1% la probabilità del Paladino incantatore di infliggere un colpo critico con ⟦Flash of Light=Lampo di Luce⟧.", 0x83a78794, 0xc8eb5579, "uu" },
  [440658] = { "Colpisce il bersaglio con lo scudo, infliggendo danni da sacro basati sul tuo indice di blocco più altri $N1 danni.", nil, 0x675f9fa9, nil, "um" },
  [440666] = { "Quando si attiva il tuo talento Rivendicazione, riduce anche la potenza d'attacco del bersaglio di $N1 per punto talento e aumenta la tua Forza, la tua Agilità e la tua potenza d'attacco del $N2% per punto talento. La durata di Rivendicazione aumenta a $D1.", nil, 0x9d03ab96, nil, "um" },
  [440667] = { "Riduce la potenza d'attacco del bersaglio di $N1.", "Potenza d'attacco ridotta di $N1.", 0x4c568392, 0x3b8db6a5, "uu" },
  [440668] = { "Potenza d'attacco aumentata del $N1%.", "Potenza d'attacco aumentata del $N1%.", 0xfe0a7d88, 0xfe93b3f4, "uu" },
  [440672] = { "Quando Giudizio o ⟦Crusader Strike=Assalto del Crociato⟧ infliggono un colpo critico, il bersaglio subisce il $N1% di danni aggiuntivi in $D1.", nil, 0x51f09583, nil, "um" },
  [440675] = { nil, "Infligge danni da sacro ogni $D1.", nil, 0x74b718e2, "mu" },
  [440720] = { nil, "È questo che si prova a essere un Paladino?", nil, 0xcab03f05, "mu" },
  [440788] = { "Incidi sul tuo mantello la runa Shield of Righteousness:\n\n$I1\nColpisce il bersaglio con lo scudo, infliggendo danni da sacro basati sul tuo indice di blocco più altri $N1 danni.", nil, 0xb62d614f, nil, "um" },
  [440789] = { "Ottieni l'abilità Shield of Righteousness:\n\n$I1\nColpisce il bersaglio con lo scudo, infliggendo danni da sacro basati sul tuo indice di blocco più altri $N1 danni.", nil, 0x60be8165, nil, "um" },
  [440790] = { "Incidi sul tuo mantello la runa Dominio Rapido:\n\n$I1\nQuando Giusta Furia non è attiva, infliggere danni con Folgore Sacra ti conferisce il $N1% del tuo Intelletto come danni magici e riduce la minaccia che generi del $N2% per $D1.\n\nSe è incisa Infusione di Luce, ottieni Luce Solare per $D2.\n\n$I2\nLuce Solare fa sì che Tempesta Divina, Assalto del Crociato e gli attacchi in mischia contro bersagli non controllati da giocatori infliggano danni da sacro aggiuntivi pari al $N5% della tua potenza magica sacra.", nil, 0x21f37d6a, nil, "um" },
  [440791] = { "Ottieni l'abilità Dominio Rapido:\n\n$I1\nQuando Giusta Furia non è attiva, infliggere danni con Folgore Sacra ti conferisce il $N1% del tuo Intelletto come danni magici e riduce la minaccia che generi del $N2% per $D1.\n\nSe è incisa Infusione di Luce, ottieni Luce Solare per $D2.\n\n$I2\nLuce Solare fa sì che Tempesta Divina, Assalto del Crociato e gli attacchi in mischia contro bersagli non controllati da giocatori infliggano danni da sacro aggiuntivi pari al $N5% della tua potenza magica sacra.", nil, 0xeaaff97e, nil, "um" },
  [440792] = { "Incidi sul tuo mantello la runa Righteous Vengeance:\n\n$I1\nQuando Giudizio o Assalto del Crociato infliggono un colpo critico, il bersaglio subisce il $N1% di danni aggiuntivi in $D1.", nil, 0xdd37e14e, nil, "um" },
  [440794] = { "Ottieni l'abilità Righteous Vengeance:\n\n$I1\nQuando Giudizio o Assalto del Crociato infliggono un colpo critico, il bersaglio subisce il $N1% di danni aggiuntivi in $D1.", nil, 0x582e0479, nil, "um" },
  [440802] = { "Lancia un globo di ghiaccio vorticante che avanza rapidamente per $D1. Mentre si muove, ogni $D2 il globo infligge $N3 danni da gelo e applica un Gelo che riduce del $N4% la velocità di movimento di tutti i nemici che attraversa. La prima volta che danneggia un nemico, il suo movimento rallenta e ha una probabilità del $N5% di attivare la runa Dita di Gelo.", nil, 0xcb2a6d8e, nil, "um" },
  [440809] = { nil, "Velocità di movimento ridotta del $N1%.", nil, 0x09876d53, "mu" },
  [440820] = { "..", nil, 0x000017b8, nil, "um" },
  [440827] = { "Gettalo in un calderone ribollente per provocare un'esplosione di gas nocivo. Non interrompe la furtività.", nil, 0x5d2eeb16, nil, "um" },
  [440829] = { "Unisci offerte di carne e ossa.", nil, 0x49295518, nil, "um" },
  [440830] = { "Infondi l'essenza della magia del sangue in un emblema cavo.", nil, 0x9ddd6f51, nil, "um" },
  [440841] = { "Rivela la tomba che nasconde un'offerta.", "Rivela la tomba che nasconde un'offerta.", 0x4a6817a6, 0x4a6817a6, "uu" },
  [440858] = { "Incidi sul tuo mantello la runa Globo Congelato:\n\n$I1\nLancia un globo di ghiaccio vorticante che avanza rapidamente per $D1. Mentre si muove, ogni $D2 il globo infligge $N3 danni da gelo e applica un Gelo che riduce del $N4% la velocità di movimento di tutti i nemici che attraversa. La prima volta che danneggia un nemico, il suo movimento rallenta e ha una probabilità del $N5% di attivare la runa Dita di Gelo.", nil, 0xf8b56c74, nil, "um" },
  [440859] = { "Ottieni l'abilità Globo Congelato:\n\n$I1\nLancia un globo di ghiaccio vorticante che avanza rapidamente per $D1. Mentre si muove, ogni $D2 il globo infligge $N3 danni da gelo e applica un Gelo che riduce del $N4% la velocità di movimento di tutti i nemici che attraversa. La prima volta che danneggia un nemico, il suo movimento rallenta e ha una probabilità del $N5% di attivare la runa Dita di Gelo.", nil, 0x6788d427, nil, "um" },
  [440873] = { nil, "Il tempo di lancio di ⟦Soul Fire=Fuoco dell'Anima⟧ è ridotto del $N1% e non consuma frammenti.", nil, 0xf95dd699, "mu" },
  [440882] = { nil, "Danni magici subiti ridotti del $N1%.", nil, 0xa6e1df00, "mu" },
  [440892] = { nil, "Resistenze magiche ridotte di $N1. Danni magici subiti aumentati del $N2%.", nil, 0x96faf3fe, "mu" },
  [440895] = { nil, "Il tuo prossimo incantesimo non periodico a bersaglio singolo ha il $N1% di probabilità di critico in più.", nil, 0xb7c01d56, "mu" },
  [440922] = { "Incidi sui tuoi stivali la runa Decimazione:\n\n$I1\nRiduce del $N1% il tempo di recupero di Fuoco dell'Anima. Quando lanci Dardo d'Ombra o Dolore Ustionante su un nemico sotto il $N2% della salute, questi infliggono il $N3% di danni in più e per i successivi $D1 il tuo Fuoco dell'Anima ha il tempo di lancio ridotto del $N5% e non costa Soul Shard.", nil, 0x19ab4ac7, nil, "um" },
  [440924] = { "Incidi sul tuo mantello la runa Marchio del Caos:\n\n$I1\nMaledice il bersaglio per $D1, riducendone le resistenze magiche di $N2 e aumentando i danni magici che subisce del $N3%. Su un bersaglio può essere attiva una sola maledizione per Stregone.", nil, 0x050e05a1, nil, "um" },
  [440926] = { "Incidi sul tuo mantello la runa Armatura Infernale:\n\n$I1\nIl tuo spirito si infonde di energia demoniaca, riducendo tutti i danni magici che subisci di una percentuale pari al $N1% della tua riduzione dei danni fisici dovuta all'Armatura. Dura $D1.", nil, 0x32bd63f1, nil, "um" },
})
